def factorial_with_prime_check(n):
    # Use a global cache to persist results across multiple calls
    memo = {}

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def factorial(n):
        if n in memo:
            return memo[n]
        if n == 0:
            memo[n] = 1
            return 1
        result = n * factorial(n - 1)
        memo[n] = result
        return result

    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    return (factorial(n), is_prime(n))
